# Function to draw the grid
def draw_grid():
    for row in range(4):
        for col in range(4):
            value = grid[row][col]
            if value != 0:
                text = FONT.render(str(value), True, (0, 0, 0))
                x = col * GRID_SIZE + GRID_SIZE // 2 - text.get_width() // 2
                y = row * GRID_SIZE + GRID_SIZE // 2 - text.get_height() // 2
                screen.blit(text, (x, y))
            else:
                pygame.draw.rect(screen, GRID_COLOR, (col * GRID_SIZE, row * GRID_SIZE, GRID_SIZE, GRID_SIZE), 2)

# Function to add a new tile
def add_new_tile():
    empty_cells = [(row, col) for row in range(4) for col in range(4) if grid[row][col] == 0]
    if empty_cells:
        row, col = empty_cells[pygame.math.Vector2(0, len(empty_cells)).x]
        grid[row][col] = 2 if pygame.math.Vector2(0, 1).x < 0.9 else 4

# Function to check if the game is over
def check_game_over():
    for row in range(4):
        for col in range(4):
            if grid[row][col] == 0:
                return False
            if row < 3 and grid[row][col] == grid[row + 1][col]:
                return False
            if col < 3 and grid[row][col] == grid[row][col + 1]:
                return False
    return True

# Function to move tiles in a specified direction
def move_tiles(direction):
    if direction == 'UP':
        for col in range(4):
            column = [grid[row][col] for row in range(4)]
            new_column = merge(column)
            for row in range(4):
                grid[row][col] = new_column[row]
    elif direction == 'DOWN':
        for col in range(4):
            column = [grid[row][col] for row in range(4)]
            new_column = merge(column[::-1])[::-1]
            for row in range(4):
                grid[row][col] = new_column[row]
    elif direction == 'LEFT':
        for row in range(4):
            row_list = grid[row]
            new_row = merge(row_list)
            grid[row] = new_row
    elif direction == 'RIGHT':
        for row in range(4):
            row_list = grid[row]
            new_row = merge(row_list[::-1])[::-1]
            grid[row] = new_row

# Function to merge tiles in a single line
def merge(line):
    new_line = [0] * 4
    index = 0
    for value in line:
        if value != 0:
            if new_line[index] == 0:
                new_line[index] = value
            elif new_line[index] == value:
                new_line[index] *= 2
                index += 1
            else:
                index += 1
                new_line[index] = value
