import random
from flask import Flask, render_template, request, jsonify

app = Flask(__name__)

# Initialize the game state
game_state = {
    'board': [[0] * 4 for _ in range(4)],
    'score': 0,
    'game_over': False
}

def initialize_game():
    """
    Initializes the game state with a new board and adds two initial tiles.
    """
    for row in range(4):
        for col in range(4):
            game_state['board'][row][col] = 0
    add_random_tile()
    add_random_tile()
    game_state['score'] = 0
    game_state['game_over'] = False

def add_random_tile():
    """
    Adds a new tile (either 2 or 4) to a random empty cell on the board.
    """
    empty_cells = [(row, col) for row in range(4) for col in range(4) if game_state['board'][row][col] == 0]
    if empty_cells:
        row, col = random.choice(empty_cells)
        game_state['board'][row][col] = 2 if random.random() < 0.9 else 4

def get_empty_cells():
    """
    Returns a list of empty cells on the board.
    """
    return [(row, col) for row in range(4) for col in range(4) if game_state['board'][row][col] == 0]

def move_tiles(direction):
    """
    Moves and merges the tiles in the specified direction.
    """
    if direction == 'up':
        for col in range(4):
            merge_tiles([game_state['board'][row][col] for row in range(4)], col)
    elif direction == 'down':
        for col in range(4):
            merge_tiles([game_state['board'][row][col] for row in range(3, -1, -1)], col)
    elif direction == 'left':
        for row in range(4):
            merge_tiles(game_state['board'][row], row)
    elif direction == 'right':
        for row in range(4):
            merge_tiles(game_state['board'][row][::-1], row)

def merge_tiles(line, index):
    """
    Merges the tiles in a single line and updates the board.
    """
    line = [num for num in line if num != 0]
    i = 0
    while i < len(line) - 1:
        if line[i] == line[i + 1]:
            line[i] *= 2
            game_state['score'] += line[i]
            del line[i + 1]
        i += 1
    line += [0] * (4 - len(line))
    for row in range(4):
        game_state['board'][index][row] = line[row]
    if get_empty_cells():
        add_random_tile()
    else:
        game_state['game_over'] = True

@app.route('/')
def index():
    """
    Renders the main page with the game interface.
    """
    return render_template('index.html', board=game_state['board'], score=game_state['score'], game_over=game_state['game_over'])

@app.route('/move', methods=['POST'])
def move():
    """
    Handles the game move request and updates the game state.
    """
    direction = request.form['direction']
    move_tiles(direction)
    return jsonify(board=game_state['board'], score=game_state['score'], game_over=game_state['game_over'])

@app.route('/restart', methods=['POST'])
def restart():
    """
    Restarts the game.
    """
    initialize_game()
    return jsonify(board=game_state['board'], score=game_state['score'], game_over=game_state['game_over'])

if __name__ == '__main__':
    initialize_game()
    app.run(debug=True)

