import sh
import tempfile
import os
from pathlib import PosixPath
from typing import Optional, Union

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """
    Given an existing archive_path, uncompress it.
    Returns a repository URL which can be used as origin URL.

    This does not deal with the case where the archive passed along does not exist.
    @param archive_path : archive file path
    @param filename: File name
    @param tmp_path: Temporary file path
    @return Repository URL
    """
    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"The archive file at {archive_path} does not exist.")

    if filename is None:
        filename = os.path.basename(archive_path)

    temp_dir = tempfile.mkdtemp(dir=tmp_path)
    extracted_path = os.path.join(temp_dir, filename.replace('.zip', '').replace('.tar', '').replace('.gz', ''))

    try:
        if archive_path.endswith('.zip'):
            sh.unzip(archive_path, '-d', temp_dir)
        elif archive_path.endswith('.tar'):
            sh.tar.xvf(archive_path, '-C', temp_dir)
        elif archive_path.endswith('.gz'):
            sh.gunzip(archive_path, '-c', '-d', temp_dir)
        else:
            raise ValueError("Unsupported archive format. Only .zip, .tar, and .gz are supported.")
    except sh.ErrorReturnCode as e:
        raise RuntimeError(f"Error occurred while extracting the archive: {e}")

    return extracted_path

