from typing import List

class Bookmarks:
    def __init__(self):
        self.categories = {}

    def add_bookmark(self, category_path: str, bookmark_name: str):
        """
        Add a bookmark to the appropriate category in the bookmarks structure.
        """
        categories = category_path.split('/')
        current_level = self.categories
        for category in categories[:-1]:
            if category not in current_level:
                current_level[category] = {}
            current_level = current_level[category]
        if categories[-1] not in current_level:
            current_level[categories[-1]] = []
        current_level[categories[-1]].append(bookmark_name)

    def to_dict(self):
        """
        Convert the bookmarks structure to a dictionary for easy serialization.
        """
        return self.categories

def from_raw_values(values: List[str]) -> Bookmarks:
    """
    Create a Bookmarks object from a list of raw bookmark string values.
    """
    bookmarks = Bookmarks()
    for value in values:
        # Split the value into category path and bookmark name
        parts = value.split('|')
        if len(parts) != 2:
            raise ValueError("Each raw bookmark value must be in the format 'category/subcategory|bookmark name'")
        category_path, bookmark_name = parts
        bookmarks.add_bookmark(category_path, bookmark_name)
    return bookmarks

